CREATE TABLE device_categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(80) NOT NULL UNIQUE,
    name VARCHAR(120) NOT NULL,
    description TEXT NOT NULL,
    icon_id VARCHAR(40) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_device_categories_slug CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_device_categories_name CHECK (btrim(name) <> ''),
    CONSTRAINT ck_device_categories_description CHECK (btrim(description) <> '')
);

CREATE INDEX idx_device_categories_active_name
    ON device_categories (active, name);

CREATE INDEX idx_device_categories_search
    ON device_categories USING GIN (
        to_tsvector('simple', coalesce(name, '') || ' ' || coalesce(description, ''))
    );

CREATE TABLE repair_services (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug VARCHAR(120) NOT NULL UNIQUE,
    name VARCHAR(160) NOT NULL,
    short_description VARCHAR(320) NOT NULL,
    detailed_description TEXT NOT NULL,
    category_id BIGINT NOT NULL,
    repair_type VARCHAR(50) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    search_vector TSVECTOR GENERATED ALWAYS AS (
        setweight(to_tsvector('simple', coalesce(name, '')), 'A') ||
        setweight(to_tsvector('simple', coalesce(short_description, '')), 'B') ||
        setweight(to_tsvector('simple', coalesce(detailed_description, '')), 'C')
    ) STORED,
    CONSTRAINT fk_repair_services_category
        FOREIGN KEY (category_id) REFERENCES device_categories (id) ON DELETE RESTRICT,
    CONSTRAINT ck_repair_services_slug CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_repair_services_name CHECK (btrim(name) <> ''),
    CONSTRAINT ck_repair_services_short_description CHECK (btrim(short_description) <> ''),
    CONSTRAINT ck_repair_services_detailed_description CHECK (btrim(detailed_description) <> ''),
    CONSTRAINT ck_repair_services_type CHECK (repair_type IN (
        'SCREEN_REPAIR',
        'BATTERY_REPLACEMENT',
        'CHARGING_PORT_REPAIR',
        'CAMERA_REPAIR',
        'AUDIO_REPAIR',
        'BUTTON_REPAIR',
        'KEYBOARD_REPAIR',
        'OVERHEATING_INSPECTION',
        'TRACKPAD_REPAIR',
        'CHARGING_CONTACT_REPAIR',
        'POWER_INSPECTION',
        'COOLING_INSPECTION',
        'STORAGE_REPLACEMENT',
        'CONNECTIVITY_REPAIR'
    ))
);

CREATE INDEX idx_repair_services_active_category_name
    ON repair_services (active, category_id, name);

CREATE INDEX idx_repair_services_active_type
    ON repair_services (active, repair_type);

CREATE INDEX idx_repair_services_search
    ON repair_services USING GIN (search_vector);

